describe('Search Filter Results Count', () => {
    beforeEach(() => {
        cy.visit('/search'); // Replace with the actual URL of the search page
    });

    it('should display the correct number of results for each filter option', () => {
        cy.get('.filter-option').each(($filter) => {
            const filterText = $filter.text();
            cy.wrap($filter).click();
            cy.get('.results-count').should('contain', `Results for ${filterText}:`);
            cy.get('.results').should('have.length.greaterThan', 0);
            cy.wrap($filter).click(); // Click again to reset the filter
        });
    });

    it('should handle no results for a filter option gracefully', () => {
        cy.get('.filter-option').contains('No Results Filter').click(); // Replace with an actual filter that yields no results
        cy.get('.results-count').should('contain', 'Results for No Results Filter: 0');
        cy.get('.results').should('have.length', 0);
    });
});
